function buildHistory12M(ticker: string, change1D: number): number[] {
  let hash = 0;
  for (let i = 0; i < ticker.length; i++) {
    hash = (hash * 31 + ticker.charCodeAt(i)) % 997;
  }
  const baseStart = 88 + (hash % 12);
  const drift = Math.max(-2.5, Math.min(3.5, 1.2 + change1D * 0.35 + ((hash % 9) - 4) * 0.25));
  const series: number[] = [];
  for (let m = 0; m < 12; m++) {
    const wave = Math.sin((m + (hash % 6)) * 0.9) * 2.4;
    const val = Math.round((baseStart + m * drift + wave) * 10) / 10;
    series.push(Math.max(45, val));
  }
  return series;
}

export const EXPANDED_5000_ASSETS: Asset[] = EXPANDED_5000_ROWS.map((row) => {
  const [ticker, name, typeCode, sectorIdx, price, change1D, metric, dividendYield, marketCap] = row;
  const type = typeCode === 0 ? 'IDX_STOCK' : typeCode === 1 ? 'US_STOCK' : 'ETF';
  const currency = typeCode === 0 ? 'IDR' : 'USD';
  const sector = SECTOR_NAMES[sectorIdx] || 'Global Equity';
  const beta =
    typeCode === 2
      ? sectorIdx === 15 ? 0.68 : sectorIdx === 16 ? 1.15 : 0.98
      : typeCode === 0
      ? sectorIdx === 0 || sectorIdx === 5 ? 0.85 : 1.08
      : sectorIdx === 1 || sectorIdx === 2 ? 1.28 : sectorIdx === 4 || sectorIdx === 11 ? 0.78 : 1.06;

  const riskRating: Asset['riskRating'] =
    beta >= 1.28 ? 'Tinggi' : beta <= 0.82 ? 'Rendah' : 'Moderat';

  const return1Y = Math.round((8.5 + change1D * 2.1 + (beta - 0.9) * 9) * 10) / 10;
  const return3Y = Math.round((return1Y * 0.85 + 2.4) * 10) / 10;

  return {
    ticker,
    name,
    type,
    sector,
    currency,
    price,
    change1D,
    return1Y,
    return3Y,
    beta,
    dividendYield,
    ...(type === 'ETF' ? { expenseRatio: metric } : { peRatio: metric }),
    marketCap,
    riskRating,
    history12M: buildHistory12M(ticker, change1D),
    description:
      type === 'IDX_STOCK'
        ? `${name} (${ticker}) tercatat di Bursa Efek Indonesia sektor ${sector} dengan kapitalisasi pasar ${marketCap}.`
        : type === 'ETF'
        ? `${name} (${ticker}) merupakan ETF global kategori ${sector} dengan AUM ${marketCap} dan rasio biaya ${metric}%.`
        : `${name} (${ticker}) adalah emiten bursa Wall Street AS sektor ${sector} dengan kapitalisasi pasar ${marketCap}.`,
  };
});
